import { describe, expect, it } from "vitest";
import { aiTextSignaturesOf } from "../src/data/ai-text-signatures";

const MUST_MATCH = [
	"🤖 Generated with [Claude Code](https://claude.com/claude-code)",
	"_Generated by [Claude Code](https://x)_",
	"Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>",
	"Co-authored-by: Claude <noreply@anthropic.com>",
	"> **DISCLAIMER:** This comment was written by an LLM, Claude Opus 5.5",
	"<sub>🤖 posted by Claude Opus 5.5 reviewed by @someone</sub>",
	"Drafted-by: Kiro (Claude Opus 5.5); reviewed by @someone",
	"> This review was generated by GitHub Copilot.",
	"Prepared with Codex.",
	"Written with help from Claude (AI); reviewed and tested by me.",
	"<sub>Written with the help of AI.</sub>",
	"Prepared with AI assistance.",
	"> AI-generated CI triage prepared with GitHub Copilot.",
	"Investigated and written with Claude Code; I reviewed it.",
	"Found and generated with Claude Code and Codex",
];

const MUST_NOT_MATCH = [
	// People with the name of a tool
	"Written by Claude Martin, thanks!",
	"Co-authored-by: Claude Debussy <claude@example.com>",
	"Posted by Devin Smith on the mailing list",
	"Generated by Jules Verne's script",
	// Talking about a footer
	'I removed the "Generated with Claude Code" line from the description.',
	'2. Removed the "Generated with Claude Code" line.',
	// Tools that are not AI
	"This file was generated by cargo.",
	"Generated with `cargo generate`.",
	"with set_current_vllm_config(vllm_config):",
	"Does it reproduce with the latest Agents SDK release? Yes",
	// Help with something other than writing
	"I reviewed this, heavily assisted by Claude.",
	"(Tested with AI assistance.)",
	"Pre-publication review by an independent model (codex) plus my own review",
	// Other wording
	"Created with AI in mind",
	"Generated with the help of a template",
	"Can you check if this was written by an AI? It reads odd.",
	"// Generated by Copilot",
];

describe("aiTextSignaturesOf", () => {
	it.each(MUST_MATCH)("matches %s", (text) => {
		expect(aiTextSignaturesOf(text)).not.toEqual([]);
	});

	it.each(MUST_NOT_MATCH)("does not match %s", (text) => {
		expect(aiTextSignaturesOf(text)).toEqual([]);
	});

	it("finds a footer at the end of a longer post", () => {
		const post = "Fixed the parser.\n\nCo-authored-by: Claude <noreply@anthropic.com>";

		expect(aiTextSignaturesOf(post)).toEqual(["trailer"]);
	});

	it("skips lines longer than 200 characters", () => {
		const longLine = `Generated with Claude Code ${"x".repeat(200)}`;

		expect(aiTextSignaturesOf(longLine)).toEqual([]);
	});
});
